package com.luminor.tavernquest.feature.hero
import androidx.lifecycle.*;import com.luminor.tavernquest.domain.repository.HeroRepository;import com.luminor.tavernquest.domain.rules.LevelCalculator;import com.luminor.tavernquest.domain.usecase.hero.CalculateStreakUseCase;import dagger.hilt.android.lifecycle.HiltViewModel;import javax.inject.Inject;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch
@HiltViewModel class HeroViewModel @Inject constructor(hero:HeroRepository,level:LevelCalculator,streakUse:CalculateStreakUseCase):ViewModel(){private val streak=MutableStateFlow(0);val ui=combine(hero.observe(),streak){h,s->HeroUiState(h,h?.let{level.calculate(it.totalXp)},s)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),HeroUiState());init{viewModelScope.launch{streak.value=streakUse()}}}
